const inputData = $input.first().json.data;
const tagName = inputData?.tags?.[0]?.name ?? null;
const webhookBody = $('Webhook').first().json.body ?? {};
const reply = webhookBody.data?.reply ?? {};
const workspaceId = String(webhookBody.event?.workspace_id ?? '').trim();
const providerCampaignId = String(webhookBody.data?.campaign?.id ?? '').trim();

// Search records2 is intentionally bounded. Resolve only one unique Airtable record;
// zero or multiple matches stay unlinked and remain retryable through the stored IDs.
const campaignMatches = $('Search records2').all()
  .map(item => item.json)
  .filter(item => item && typeof item.id === 'string' && item.id.startsWith('rec'));
const uniqueCampaignMatches = [...new Map(campaignMatches.map(item => [item.id, item])).values()];
const campaignRecordId = uniqueCampaignMatches.length === 1 ? uniqueCampaignMatches[0].id : null;
const campaignResolutionStatus = uniqueCampaignMatches.length === 1
  ? 'resolved'
  : uniqueCampaignMatches.length === 0 ? 'unresolved_no_match' : 'unresolved_ambiguous';

// A bounced event may include a normal tracked reply, not a delivery report.
// Never infer an SMTP code from an arbitrary number or quoted signature.
const texts = [reply.text_body, reply.html_body]
  .filter(v => typeof v === 'string')
  .map(v => v.replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/(?:p|div|li)>/gi, '\n').replace(/<[^>]*>/g, '').replace(/&nbsp;/gi, ' '));
const patterns = [
  /(?:^|\n)\s*Diagnostic-Code:\s*smtp\s*;\s*([45]\d{2})(?=[\s-]|$)/im,
  /\b(?:SMTP(?:\s+(?:error|reply|response|status|code))?|remote server returned|server (?:said|returned)|SMTP error from remote mail server[^\n]*?:)\s*[:=]?\s*["']?([45]\d{2})(?=[\s-]|$)/i,
  /(?:^|\n)\s*([45]\d{2})[ -]+[45]\.\d{1,3}\.\d{1,3}(?=\s|$)/m,
  /(?:^|\n)\s*([45]\d{2})[ -]+(?:requested action (?:not taken|aborted)|(?:mailbox|user|recipient|address) (?:unavailable|unknown|not found|does not exist|rejected)|no such (?:user|mailbox)|message (?:rejected|blocked)|service (?:unavailable|not available)|relay(?:ing)? (?:denied|not permitted))/im
];
let smtpCode = null;
for (const pattern of patterns) {
  for (const text of texts) {
    const match = text.match(pattern);
    if (match) { smtpCode = match[1]; break; }
  }
  if (smtpCode) break;
}

// Match the existing Airtable select options; retain unsupported codes as evidence.
const allowed = new Set(['554','553','552','551','550','452','451','450','421','454','521']);
return [{ json: {
  tag_name: tagName,
  bounce_code: smtpCode && allowed.has(smtpCode) ? smtpCode : 'Unk',
  bounce_type: smtpCode ? (smtpCode.startsWith('4') ? 'Soft Bounce' : 'Hard Bounce') : null,
  detected_smtp_code: smtpCode,
  bounce_diagnostic_status: !smtpCode ? 'Missing diagnostic: no explicit SMTP response in webhook reply' : allowed.has(smtpCode) ? 'Parsed SMTP response' : 'SMTP code not in Airtable options',
  campaign_record_id: campaignRecordId,
  campaign_resolution_status: campaignResolutionStatus,
  campaign_match_count: uniqueCampaignMatches.length,
  campaign_workspace_id: workspaceId,
  provider_campaign_id: providerCampaignId
} }];

const b=$('Webhook').first().json.body||{},d=b.data||{},r=d.reply||{};
const workspace=String(b.event?.workspace_id||''),campaign=String(d.campaign?.id||''),lead=String(d.lead?.id||'');
const mailbox=String(d.sender_email?.email||'').trim().toLowerCase();
if(!/^\d+$/.test(workspace)||!/^\d+$/.test(campaign)||!/^\d+$/.test(lead)||!mailbox.includes('@'))throw Error('Insufficient stable campaign identity to create a conversation; manual review required');
return [{json:{conversationKey:['emailbison',workspace,campaign,lead,mailbox].join(':'),prior:$json}}];
